/* ❌ OLD: CSS multi-columns approximate masonry but reflow content
   top-to-bottom per column. Card #1 and #2 sit in column 1 while
   column 4 stays empty until the page is tall enough — DOM order
   becomes vertical-column order, breaking reading order and focus. */

.wall {
  column-count: 4; /* ❌ OLD: columns, not masonry */
  column-gap: 16px;
}

.wall .card {
  break-inside: avoid; /* ❌ OLD: fragile column-break rule */
}

/* Items fill column 1, then column 2, etc. — the first four cards are
   all in the first column; visually and semantically this is not
   masonry (shortest-column placement), and keyboard order is wrong. */

/* ✅ NEW: Grid masonry places each item into the currently shortest
   column, preserving DOM order and reading order, with no gaps. */

.wall {
  display: grid;
  grid-template-columns: repeat(4, 1fr); /* fixed grid-axis tracks */
  grid-template-rows: masonry; /* ✅ NEW: masonry flow on the block axis */
  gap: 16px;
}

/* Cards keep their intrinsic heights; the algorithm tracks each
   column's running position and drops the next card into the shortest
   one. Items flow left-to-right, top-to-bottom in DOM order — no
   vertical-column reordering. (Draft spec: enable the flag in
   Chromium, stable in Firefox 128+.) */
